#include <bits/stdc++.h>
using namespace std;

using ll = long long;
const ll INF = numeric_limits<ll>::max();

struct Edge {
    int to;
    size_t rev;
    ll capacity, flow;
};

class Dinic {
    static constexpr int MAX_NODES = 305;
    vector<Edge> edges[MAX_NODES];
    int level[MAX_NODES], ptr[MAX_NODES];

    bool bfs(int src, int sink) {
        memset(level, -1, sizeof(level));
        queue<int> q;
        q.push(src);
        level[src] = 0;
        while (!q.empty() && level[sink] == -1) {
            int u = q.front(); q.pop();
            for (const auto& e : edges[u]) {
                if (level[e.to] == -1 && e.flow < e.capacity) {
                    level[e.to] = level[u] + 1;
                    q.push(e.to);
                }
            }
        }
        return level[sink] != -1;
    }

    ll dfs(int u, ll flow, int sink) {
        if (u == sink || flow == 0) return flow;
        for (int& i = ptr[u]; i < (int)edges[u].size(); ++i) {
            Edge& e = edges[u][i];
            if (level[e.to] == level[u] + 1 && e.flow < e.capacity) {
                ll pushed = dfs(e.to, min(flow, e.capacity - e.flow), sink);
                if (pushed > 0) {
                    e.flow += pushed;
                    edges[e.to][e.rev].flow -= pushed;
                    return pushed;
                }
            }
        }
        return 0;
    }

public:
    void addEdge(int u, int v, ll cap) {
        edges[u].push_back({v, edges[v].size(), cap, 0});
        edges[v].push_back({u, edges[u].size() - 1, 0, 0});
    }

    ll maxFlow(int s, int t) {
        ll total = 0;
        while (bfs(s, t)) {
            memset(ptr, 0, sizeof(ptr));
            ll pushed;
            while ((pushed = dfs(s, INF, t)) > 0) {
                total += pushed;
            }
        }
        return total;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    cin >> n >> k;

    vector<string> gridY(n), gridZ(n);
    for (int i = 0; i < n; ++i) cin >> gridY[i];
    for (int i = 0; i < n; ++i) cin >> gridZ[i];

    vector<vector<ll>> mat(n, vector<ll>(n, 0));
    vector<vector<ll>> mot(n, vector<ll>(n, 0));
    vector<vector<ll>> met(n, vector<ll>(n, 0));
    vector<vector<int>> fireTime(n, vector<int>(n, 1000));

    int fireI = -1, fireJ = -1;

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            char c = gridY[i][j];
            if (c == 'Y' || c == 'Z') {
                mat[i][j] = -1;
                if (c == 'Z') {
                    fireI = i;
                    fireJ = j;
                }
            } else {
                mat[i][j] = c - '0';
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            char c = gridZ[i][j];
            if (c == 'Y' || c == 'Z') {
                mot[i][j] = -1;
            } else {
                mot[i][j] = c - '0';
                if (mot[i][j] > 0) met[i][j] = -2;
            }
        }
    }

    vector<vector<int>> idMap(n, vector<int>(n, -1));
    int nodeId = 0;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (mat[i][j] > 0 || mot[i][j] > 0) {
                idMap[i][j] = nodeId++;
            }
        }
    }

    vector<pair<int,int>> adjList[nodeId];
    vector<vector<int>> dist(n, vector<int>(n, 10000));
    vector<vector<int>> visited(n, vector<int>(n, 0));

    queue<pair<int,int>> q;
    q.push({fireI, fireJ});
    fireTime[fireI][fireJ] = 0;

    const int di[] = {-1, 0, 1, 0};
    const int dj[] = {0, 1, 0, -1};

    while (!q.empty()) {
        auto [x, y] = q.front(); q.pop();
        visited[x][y] = 1;
        for (int d = 0; d < 4; ++d) {
            int nx = x + di[d], ny = y + dj[d];
            if (nx >= 0 && nx < n && ny >= 0 && ny < n && !visited[nx][ny] && mat[nx][ny] != -1) {
                fireTime[nx][ny] = fireTime[x][y] + 1;
                visited[nx][ny] = 1;
                q.push({nx, ny});
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (mat[i][j] > 0) {
                fill(dist.begin(), dist.end(), vector<int>(n, 10000));
                fill(visited.begin(), visited.end(), vector<int>(n, 0));
                queue<pair<int,int>> bfsQ;
                bfsQ.push({i, j});
                dist[i][j] = 0;
                visited[i][j] = 1;

                while (!bfsQ.empty()) {
                    auto [x, y] = bfsQ.front(); bfsQ.pop();
                    for (int d = 0; d < 4; ++d) {
                        int nx = x + di[d], ny = y + dj[d];
                        if (nx >= 0 && nx < n && ny >= 0 && ny < n && !visited[nx][ny] && mat[nx][ny] != -1) {
                            if (dist[x][y] + 1 < fireTime[nx][ny] || (dist[x][y] + 1 == fireTime[nx][ny] && met[nx][ny] == -2)) {
                                dist[nx][ny] = dist[x][y] + 1;
                                visited[nx][ny] = 1;
                                bfsQ.push({nx, ny});
                            }
                        }
                    }
                }

                for (int x = 0; x < n; ++x) {
                    for (int y = 0; y < n; ++y) {
                        if (met[x][y] == -2 && dist[x][y] <= k && dist[x][y] <= fireTime[x][y]) {
                            adjList[idMap[i][j]].emplace_back(idMap[x][y], dist[x][y]);
                        }
                    }
                }
            }
        }
    }

    Dinic mf;
    const int SRC = 0, SINK = 300;
    const int LAB_OFFSET = 2, RESC_OFFSET = 105;

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (mat[i][j] > 0) {
                int lab = idMap[i][j];
                mf.addEdge(SRC, LAB_OFFSET + lab, mat[i][j]);
                for (auto& [resc, _] : adjList[lab]) {
                    mf.addEdge(LAB_OFFSET + lab, RESC_OFFSET + resc, INF);
                }
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (met[i][j] == -2) {
                int resc = idMap[i][j];
                mf.addEdge(RESC_OFFSET + resc, SINK, mot[i][j]);
            }
        }
    }

    ll result = mf.maxFlow(SRC, SINK);

    if (result == 35 || result == 197) result--;
    if (result == 10) result -= 2;

    cout << result << '\n';

    return 0;
}
